.rfp-tile__vid { background: linear-gradient(135deg, #1a3a5c 0%, #0f2140 100%); font-size: 22px; }
.rfp-tile__doc { background: #2a2a2a; font-size: 11px; letter-spacing: 0.08em; }
.rfp-tile__name {
